{
  "cards": {
    "cover": {
      "narration": "Phu Quoc, 7 days, 8 sun-soaked humans calling themselves Beach Eight.",
      "headline": "Phu Quoc"
    },
    "critters": {
      "narration": "You counted 11 forms and met 6 brand-new locals."
    },
    "route": {
      "narration": "From Duong Dong to Sao Beach to Hon Thom to Vinpearl, 155.7 km of island road.",
      "line": "The longest leg, Duong Dong to Hon Thom, ran 31.2 km in 50 minutes with Mr Long, who drove 120.4 km of the route."
    },
    "awards": {
      "narration": "Now the awards, 1 for each of the 8 of you."
    },
    "receipt": {
      "narration": "The till reads VND 42,600,000, VND 5,325,000 each, against a plan of VND 40,000,000.",
      "line": "Terima kasih (thank you), Phu Quoc; worth every one of the 88 expenses."
    },
    "got_away": {
      "narration": "An epic one got away: 3 sightings, 2 forms found of 4 total.",
      "line": "Gus and Hal missed it this time, and the tide has not said when it returns."
    },
    "stamp": {
      "narration": "Sign here, Beach Eight; this one goes on your pass."
    },
    "postcard": {
      "narration": "Last card, all of you grinning in my head.",
      "line": "Phu Quoc was warm, loud, and ours."
    }
  },
  "awards": [
    {
      "user_id": "0199a0f2-0000-7000-8000-000000000001",
      "title": "Shutterbug supreme",
      "line": "212 photos out of the crew's 540, a 39% share of every frame."
    },
    {
      "user_id": "0199a0f2-0000-7000-8000-000000000002",
      "title": "Ride logger",
      "line": "14 rides logged out of 20, so 70% of the turns."
    },
    {
      "user_id": "0199a0f2-0000-7000-8000-000000000003",
      "title": "Keeper of receipts",
      "line": "30 expenses logged out of 88, keeping 34% of the paper trail."
    },
    {
      "user_id": "0199a0f2-0000-7000-8000-000000000004",
      "title": "Master planner",
      "line": "11 plan edits out of 15, shaping 73% of the day."
    },
    {
      "user_id": "0199a0f2-0000-7000-8000-000000000005",
      "title": "Explorer",
      "line": "17 places out of 40, a 43% share of every stop."
    },
    {
      "user_id": "0199a0f2-0000-7000-8000-000000000006",
      "title": "Critter whisperer",
      "line": "5 finds out of 11, 45% of all new faces."
    },
    {
      "user_id": "0199a0f2-0000-7000-8000-000000000007",
      "title": "Good company",
      "line": "No numbers needed; thank you for coming, Gus."
    },
    {
      "user_id": "0199a0f2-0000-7000-8000-000000000008",
      "title": "Good company",
      "line": "No numbers needed; thank you for coming, Hal."
    }
  ]
}
